package strategy

import (
	"context"
	"log/slog"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/proclive"
)

// SessionResolution says how a session was arrived at, so a caller can tell an
// exact answer from a guess.
//
// This exists because the guess is genuinely useful to a human — someone who
// asks which session is current in a terminal means "the one that has been
// working here" — and genuinely dangerous to an agent, which means "mine" and
// may go on to act on the answer. One command can serve both only if it says
// which question it answered.
type SessionResolution string

const (
	// ResolutionCallerEnv means the calling process's own environment named
	// the session: the agent running us published its session ID and we read
	// it back. The only tier that is an identification rather than an
	// inference.
	ResolutionCallerEnv SessionResolution = "caller-env"

	// ResolutionAncestry means no environment variable was available, but a
	// session's recorded owner process is an ancestor of this one — so that
	// session's agent spawned us, however indirectly.
	ResolutionAncestry SessionResolution = "ancestry"

	// ResolutionWorktree means nothing identified the caller, and this is the
	// most recently active session recorded in the current worktree.
	ResolutionWorktree SessionResolution = "worktree"

	// ResolutionOtherWorktree means the current worktree has no sessions at
	// all, and this is the most recently active session from somewhere else in
	// the shared store. Correct for "what has been happening in this repo",
	// never evidence about the caller — worktrees share one session store, so
	// this can be any of dozens of unrelated sessions.
	ResolutionOtherWorktree SessionResolution = "other-worktree"

	// ResolutionNone means no session was found by any tier.
	ResolutionNone SessionResolution = ""
)

// IsCaller reports whether the resolution actually identified the calling
// process's own session, rather than inferring a plausible one. Gate anything
// that acts on a session — as opposed to merely displaying it — on this.
func (r SessionResolution) IsCaller() bool {
	return r == ResolutionCallerEnv || r == ResolutionAncestry
}

// ResolvedSession is a session plus the provenance of how it was picked.
type ResolvedSession struct {
	SessionID  string
	Resolution SessionResolution

	// AgentType is the agent that claimed the session, set only for
	// ResolutionCallerEnv — the environment says which agent published the ID
	// before any state has been loaded, and that is worth reporting even when
	// Tracked is false.
	AgentType types.AgentType

	// Tracked reports whether Entire holds session state for SessionID. False
	// only on the ResolutionCallerEnv tier, where the agent named a session
	// Entire has not recorded: hooks are not installed, they failed, or the
	// session's first turn has not happened yet (state is created at turn
	// start). That combination is a diagnosis worth surfacing rather than an
	// error — the caller is genuinely in a session, and Entire is genuinely
	// not tracking it.
	Tracked bool
}

// Found reports whether any session was resolved.
func (r ResolvedSession) Found() bool { return r.SessionID != "" }

// ResolveCallerSession answers "which session is running this process?",
// falling back to "which session is current here?" when nothing can identify
// the caller. Tiers, strongest first:
//
//  1. The caller's own environment (agent.CallerSessionCandidates).
//  2. Process ancestry against each session's recorded owner.
//  3. The most recently active session recorded in this worktree.
//  4. The most recently active session anywhere in the shared store.
//
// Every tier is reported through Resolution, and the two weak ones are not
// silently interchangeable with the strong ones — which is the whole point.
// `entire session current` used to collapse tiers 3 and 4 and report either as
// "the active session for the current worktree", so in a worktree with no
// sessions of its own it returned a live session belonging to a different
// worktree, indistinguishably from the real thing. An agent that read that ID
// back and acted on it operated on someone else's session.
//
// Ordering tiers 1 and 2 this way is deliberate. Tier 1 is what the vendor
// deliberately published about the process it spawned; tier 2 infers from a
// process tree, is unavailable on Windows, and depends on an owner having been
// recorded at some turn start. Tier 1 is also cheaper: a few env reads against
// a state listing plus a proc walk.
func ResolveCallerSession(ctx context.Context) ResolvedSession {
	states, err := ListSessionStates(ctx)
	if err != nil {
		logging.Debug(logging.WithComponent(ctx, "session"),
			"caller session resolution: cannot list session states",
			slog.String("error", err.Error()))
		states = nil
	}

	if resolved, ok := resolveCallerFromEnv(ctx, states); ok {
		return resolved
	}
	if id := sessionIDByOwnerAncestry(ctx, states); id != "" {
		return ResolvedSession{SessionID: id, Resolution: ResolutionAncestry, Tracked: true}
	}
	if id := mostRecentSessionID(sessionStatesForCurrentWorktree(ctx, states)); id != "" {
		return ResolvedSession{SessionID: id, Resolution: ResolutionWorktree, Tracked: true}
	}
	if id := mostRecentSessionID(states); id != "" {
		return ResolvedSession{SessionID: id, Resolution: ResolutionOtherWorktree, Tracked: true}
	}
	return ResolvedSession{Resolution: ResolutionNone}
}

// resolveCallerFromEnv picks between the agents that claim to have spawned us.
//
// Several claims at once is the normal nested case rather than a conflict: a
// `codex exec` run from Claude Code's shell tool inherits the outer agent's
// variables through the inner agent's own process, so both are set. The
// innermost is the answer, and the environment cannot order them — so
// candidates that Entire tracks are ranked by how near their owner process is
// in our ancestry, exactly as commit linking ranks its own candidates.
//
// When ancestry cannot separate them (Windows, an owner never recorded, a
// state listing that failed), the most recently interacting tracked candidate
// wins: in a nested pair the inner agent is the one doing the work, so it is
// the one that just interacted.
//
// A claim Entire does not track is kept only when no tracked claim exists at
// all. It carries a real diagnosis — we are demonstrably inside a session that
// Entire is not recording — but a tracked session is strictly more useful, and
// on the nested path the untracked claim is often just the outer agent.
func resolveCallerFromEnv(ctx context.Context, states []*SessionState) (ResolvedSession, bool) {
	candidates := agent.CallerSessionCandidates()
	if len(candidates) == 0 {
		return ResolvedSession{}, false
	}

	byID := make(map[string]*SessionState, len(states))
	for _, state := range states {
		byID[state.SessionID] = state
	}
	// Snapshot the ancestry once for every candidate, not once per candidate:
	// each call walks the process tree and reads the hostname and boot ID.
	ancestry, haveAncestry := proclive.CurrentAncestry()

	var best ResolvedSession
	var bestState *SessionState
	bestDepth := -1
	for _, candidate := range candidates {
		state, tracked := byID[candidate.SessionID]
		resolved := ResolvedSession{
			SessionID:  candidate.SessionID,
			Resolution: ResolutionCallerEnv,
			AgentType:  candidate.AgentType,
			Tracked:    tracked,
		}
		if !tracked {
			if !best.Found() {
				best = resolved
			}
			continue
		}
		depth := -1
		if haveAncestry && state.Owner != nil {
			depth = ancestry.Depth(*state.Owner)
		}
		if !best.Tracked || isNearerCaller(depth, bestDepth, state, bestState) {
			best, bestState, bestDepth = resolved, state, depth
		}
	}

	if best.Found() {
		logging.Debug(logging.WithComponent(ctx, "session"),
			"caller session resolved from environment",
			slog.String("session_id", best.SessionID),
			slog.String("agent_type", string(best.AgentType)),
			slog.Bool("tracked", best.Tracked),
			slog.Int("candidates", len(candidates)),
			slog.Int("ancestry_depth", bestDepth))
	}
	return best, best.Found()
}

// isNearerCaller reports whether a candidate at depth beats the incumbent at
// bestDepth. A resolved ancestry depth (>= 0) always beats an unresolved one,
// nearer beats farther, and an unresolved pair falls back to whichever
// interacted more recently.
func isNearerCaller(depth, bestDepth int, state, bestState *SessionState) bool {
	if depth >= 0 && bestDepth < 0 {
		return true
	}
	if depth >= 0 && bestDepth >= 0 {
		return depth < bestDepth
	}
	if depth < 0 && bestDepth >= 0 {
		return false
	}
	return interactedAfter(state, bestState)
}

// sessionIDByOwnerAncestry returns the session whose recorded owner process is
// the nearest ancestor of this one, or "" when none is.
//
// This is the tier that covers the agents which publish no session ID — Gemini
// CLI and opencode today — and any hook context the environment did not reach.
// It is the same match commit linking performs
// (findSessionByCommitAncestry): the owner fingerprint carries host, boot and
// start-time guards, so a recycled PID or an identity recorded on another
// machine cannot match, and nearest-ancestor-wins resolves nesting. Returns ""
// on platforms that cannot introspect processes (Windows), which is what makes
// the weaker tiers below still necessary.
func sessionIDByOwnerAncestry(ctx context.Context, states []*SessionState) string {
	ancestry, ok := proclive.CurrentAncestry()
	if !ok {
		return ""
	}
	var best *SessionState
	bestDepth := -1
	for _, state := range states {
		if state.Owner == nil || state.Kind.IsImported() || state.AdoptedIntoWorktreePath != "" {
			continue
		}
		depth := ancestry.Depth(*state.Owner)
		if depth < 0 {
			continue
		}
		if best == nil || depth < bestDepth || (depth == bestDepth && interactedAfter(state, best)) {
			best, bestDepth = state, depth
		}
	}
	if best == nil {
		return ""
	}
	logging.Debug(logging.WithComponent(ctx, "session"),
		"caller session resolved from process ancestry",
		slog.String("session_id", best.SessionID),
		slog.Int("owner_pid", best.Owner.PID),
		slog.Int("ancestry_depth", bestDepth))
	return best.SessionID
}

