		}
		if requireWorktreePath && state.WorktreePath == "" {
			continue
		}
		depth := ancestry.Depth(*state.Owner)
		if depth < 0 {
			continue
		}
		if best == nil || isNearerOwner(depth, bestDepth, state, best) {
			best, bestDepth = state, depth
		}
	}
	return best, bestDepth
